const { tmpdir } = await import('node:os');
const docPath = process.env.DOC_PATH;
if (!docPath) { throw new Error('DOC_PATH missing'); }
const outPath = `${tmpdir()}/output.pdf`;
globalThis.docPath = docPath;
globalThis.outPath = outPath;

const { readFileSync, writeFileSync } = await import('node:fs');
const mod = await import('office-to-pdf');
const toPdf = mod.default || mod;
const buffer = readFileSync(globalThis.docPath);
const pdfBuffer = await toPdf(buffer);
writeFileSync(globalThis.outPath, pdfBuffer);
globalThis.pdfPath = globalThis.outPath;
